                      border: 'none',
                      borderRadius: '10px',
                      padding: '12px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: '8px'
                    }}
                  >
                    ⚙️ Search Preferences
                  </button>
                </div>

                <div style={{ marginBottom: '20px' }}>
                  <h5 style={{ marginBottom: '10px' }}>Daily Stats</h5>
                  <div style={{
                    background: '#f5f5f5',
                    borderRadius: '10px',
                    padding: '15px'
                  }}>
                    <p style={{ margin: '0 0 5px 0', fontSize: '14px' }}>
                      Interests today: {appState.dailySwipeCount}/{appState.maxDailySwipes}
                    </p>
                    <div style={{
                      background: '#ddd',
                      borderRadius: '5px',
                      height: '8px',
                      overflow: 'hidden'
                    }}>
                      <div style={{
                        background: '#4CAF50',
                        height: '100%',
                        width: `${(appState.dailySwipeCount / appState.maxDailySwipes) * 100}%`,
                        transition: 'width 0.3s ease'
                      }} />
                    </div>
                  </div>
                </div>
              </>
            ) : (
              <>
                <div style={{ marginBottom: '20px' }}>
                  <h5 style={{ marginBottom: '15px' }}>Seller Dashboard</h5>

                  <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#667eea' }}>12</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Active Listings</div>
                    </div>

                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#4CAF50' }}>8</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Sales Completed</div>
                    </div>

                    <div style={{
                      background: '#f5f5f5',
                      borderRadius: '10px',
                      padding: '15px',
                      textAlign: 'center'
                    }}>
                      <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#ff9800' }}>2.3h</div>
                      <div style={{ fontSize: '12px', color: '#666' }}>Avg Response Time</div>
                    </div>
                  </div>

                  <button
                    onClick={() => updateState({ showMyListings: true, showProfile: false })}
                    style={{
                      width: '100%',
                      background: '#667eea',
                      color: 'white',
                      border: 'none',
                      borderRadius: '10px',
                      padding: '12px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      marginTop: '15px'
                    }}
                  >
                    📝 Manage Listings
                </button>
                </div>
              </>
            )}

            <button
              onClick={signOut}
              style={{
                width: '100%',
                background: '#ff4444',
                color: 'white',
                border: 'none',
                borderRadius: '10px',
                padding: '12px',
                fontWeight: 'bold',
                cursor: 'pointer',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: '8px'
              }}
            >
              <LogOut size={16} />
              Sign Out
            </button>
          </div>
        </div>
      )}

      {/* Overlay for profile panel */}
      {appState.showProfile && (
        <div
          style={{
            position: 'fixed',
            top: 'max(0px, env(safe-area-inset-top))',
            left: 0,
            right: 0,
            bottom: 0,
            background: 'rgba(0,0,0,0.5)',
            zIndex: 999
          }}
          onClick={() => updateState({ showProfile: false })}
        />
      )}

      {/* Bottom Navigation - Always visible when authenticated */}
      <BottomNavigation 
        currentView={appState.currentView}
        currentMode={appState.currentMode}
        onViewChange={(view) => {
          console.log('Changing view to:', view);
          updateState({ 
            currentView: view,
            showChats: view === 'chats',
            showProfile: view === 'profile'
          });
        }}
        onModeChange={(mode) => {
          console.log('Changing mode to:', mode);
          updateState({ currentMode: mode });
        }}
      />
    </>
  );
};

const App = () => (
  <AuthProvider>
    <SwipeMarketplace />
  </AuthProvider>
);

export default App;
